import os, json, math
import numpy as np

# Test-only analysis: no training, no GPU
def test():
    base_dir = "storage/ariadne/analyses"
    percond_dir = os.path.join(base_dir, "fourier_learn_gamma_per_condition")
    gamma_dir = os.path.join(base_dir, "fourier_learn_gamma_export_v2")

    # Trials available from prior exports (base seed 42 set)
    trials = [43, 44, 45]
    T = 32

    percond = []  # list of dicts: condition -> np.array(T,)
    gammas = []   # list of np.array(T,)

    # Load γ[t]
    for tr in trials:
        gpath = os.path.join(gamma_dir, f"trial_{tr}.json")
        if not os.path.exists(gpath):
            continue
        with open(gpath, "r") as f:
            gobj = json.load(f)
        # Try common keys
        g = None
        for k in ["gamma", "gamma_profile", "gamma_t", "gamma_values"]:
            if k in gobj:
                g = np.array(gobj[k], dtype=float)
                break
        if g is None:
            # fallback: try nested
            if "params" in gobj and "gamma" in gobj["params"]:
                g = np.array(gobj["params"]["gamma"], dtype=float)
        if g is None or g.shape[0] != T:
            continue
        gammas.append(g)

    # Load per-condition step MAEs
    for tr in trials:
        ppath = os.path.join(percond_dir, f"trial_{tr}.json")
        if not os.path.exists(ppath):
            continue
        with open(ppath, "r") as f:
            pobj = json.load(f)
        # Accept several possible schemas
        cond_map = {}
        if "per_condition_step_mae" in pobj:
            src = pobj["per_condition_step_mae"]
        elif "val_mae_by_condition" in pobj:
            src = pobj["val_mae_by_condition"]
        else:
            src = {}
        for ck, v in src.items():
            arr = np.array(v, dtype=float)
            if arr.ndim == 1 and arr.shape[0] == T:
                cond_map[str(ck)] = arr
        if cond_map:
            percond.append(cond_map)

    summary = {
        "trials_used": trials,
        "loaded_gamma_count": len(gammas),
        "loaded_per_condition_count": len(percond),
    }

    if not gammas or not percond:
        out = {
            "ok": False,
            "reason": "Missing gamma or per-condition files",
            **summary,
        }
    else:
        G = np.vstack(gammas)                              # (S,T)
        gamma_mean = G.mean(axis=0)                        # (T,)
        gamma_std  = G.std(axis=0)

        # Aggregate per-condition MAE across seeds for each condition
        # Build union of condition keys
        keys = set()
        for m in percond:
            keys |= set(m.keys())
        # Drop conditions with any NaN rows
        cond_stats = {}
        for ck in sorted(keys):
            mats = []
            for m in percond:
                if ck in m:
                    mats.append(m[ck])
            if not mats:
                continue
            M = np.vstack(mats)                            # (#seeds_for_ck, T)
            if np.isnan(M).any():
                # Ignore this condition due to NaNs
                continue
            cond_stats[ck] = {
                "mean": M.mean(axis=0).tolist(),
                "std":  M.std(axis=0).tolist(),
                "count": int(M.shape[0]),
            }

        # Define "hard" and "easy" groups heuristically if present
        hard_candidates = [k for k in cond_stats.keys() if k.lower() in ("cond7", "7", "condition7")]
        easy_candidates = [k for k in cond_stats.keys() if k.lower() in ("cond1", "1", "condition1", "cond6", "6", "condition6")]
        hard_key = hard_candidates[0] if hard_candidates else None
        easy_key = easy_candidates[0] if easy_candidates else None

        # Build step-wise difficulty (mean across all available conditions)
        all_means = [np.array(v["mean"], dtype=float) for v in cond_stats.values()]
        if all_means:
            step_mae_mean = np.vstack(all_means).mean(axis=0)  # (T,)
        else:
            step_mae_mean = np.full((T,), np.nan)

        # Correlations
        def safe_corr(a, b):
            a = np.asarray(a, dtype=float)
            b = np.asarray(b, dtype=float)
            if np.isnan(a).any() or np.isnan(b).any():
                return None
            if a.std() == 0 or b.std() == 0:
                return None
            return float(np.corrcoef(a, b)[0,1])

        corr_gamma_vs_mean_mae = safe_corr(gamma_mean, step_mae_mean)

        # Hard-vs-easy gap and correlation with gamma
        hard_vs_easy = None
        corr_gamma_vs_gap = None
        if hard_key and easy_key:
            hard_mean = np.array(cond_stats[hard_key]["mean"], dtype=float)
            easy_mean = np.array(cond_stats[easy_key]["mean"], dtype=float)
            hard_vs_easy = (hard_mean - easy_mean).tolist()
            corr_gamma_vs_gap = safe_corr(gamma_mean, hard_mean - easy_mean)

        # Simple gain heuristic: if gamma is lower at hardest steps (largest MAE),
        # increasing gamma there could help. We quantify rough potential as
        # normalized dot(-gamma_z, mae_z) where z-scores are used.
        def z(x):
            x = np.asarray(x, dtype=float)
            return (x - x.mean()) / (x.std() + 1e-8)
        if not np.isnan(step_mae_mean).any():
            potential = float(np.dot(-z(gamma_mean), z(step_mae_mean)) / T)
        else:
            potential = None

        out = {
            "ok": True,
            **summary,
            "gamma_mean": gamma_mean.tolist(),
            "gamma_std": gamma_std.tolist(),
            "corr_gamma_vs_step_mae_mean": corr_gamma_vs_mean_mae,
            "hard_key": hard_key,
            "easy_key": easy_key,
            "hard_minus_easy": hard_vs_easy,
            "corr_gamma_vs_hard_easy_gap": corr_gamma_vs_gap,
            "potential_alignment_score": potential,
            "conditions_analyzed": {k: {"count": v["count"]} for k,v in cond_stats.items()},
        }

    # Write summary JSON
    out_path = os.path.join(base_dir, "cond_gamma_correlation.json")
    with open(out_path, "w") as f:
        json.dump(out, f, indent=2)

    print("Analysis complete. Summary ->", out_path)
    return "OK"
